  if (priority === "high") return "border-orange-400/40 bg-orange-500/10 text-orange-100";
  if (priority === "normal") return "border-sky-400/40 bg-sky-500/10 text-sky-100";
  return "border-white/20 bg-white/10 text-slate-100";
}

